INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Abklären rechtlicher Aspekte Teil der Initiierung?', 2, '[{"text": "Ja", "correct": true, "because": "Rechtliche Rahmenbedingungen prüfen"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Initiierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Abklären rechtlicher Aspekte?', 3, '[{"text": "Rechtskonformität sicherstellen", "correct": true, "because": "Verhindert Verstöße"}, {"text": "Teamgröße bestimmen", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten sofort senken", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rechtliche Aspekte beeinflussen die Projektfreigabe. b) Sie werden erst nach Projektstart geklärt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, vor Start nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der rechtlichen Abklärung untersucht?', 4, '[{"text": "Datenschutzvorschriften", "correct": true, "because": "Wichtig für IT-Projekte"}, {"text": "Teamzufriedenheit", "correct": false, "because": "Kein rechtlicher Faktor"}, {"text": "Vertragsbedingungen", "correct": true, "because": "Regeln Zusammenarbeit"}, {"text": "Lizenzbestimmungen", "correct": true, "because": "Betreffen Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne rechtliche Abklärung starten?', 2, '[{"text": "Nein", "correct": true, "because": "Risiko von Verstößen"}, {"text": "Ja", "correct": false, "because": "Rechtliche Grundlage fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft beim Abklären rechtlicher Aspekte?', 3, '[{"text": "Rechtsberatung einholen", "correct": true, "because": "Sichert Expertise"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Nachweis"}, {"text": "Zufällige Annahmen", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die rechtliche Abklärung nur für IT-Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher rechtliche Aspekt ist für IT-Projekte zentral?', 3, '[{"text": "Datenschutz (z. B. DSGVO)", "correct": true, "because": "Regelt Datenverarbeitung"}, {"text": "Arbeitszeiten", "correct": false, "because": "Weniger projektbezogen"}, {"text": "Teamstruktur", "correct": false, "because": "Kein rechtlicher Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rechtliche Abklärung schützt vor Risiken. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne rechtliche Abklärung?', 3, '[{"text": "Rechtliche Verstöße drohen", "correct": true, "because": "Regeln unklar"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Strafen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können rechtliche Aspekte in der Initiierung ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Risiko von Konsequenzen"}, {"text": "Ja", "correct": false, "because": "Pflicht vor Start"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine rechtliche Abklärung?', 3, '[{"text": "Prüfung der DSGVO für eine App", "correct": true, "because": "Konkret und relevant"}, {"text": "Irgendwas wird schon gehen", "correct": false, "because": "Zu ungenau"}, {"text": "Team soll motiviert sein", "correct": false, "because": "Kein rechtlicher Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die rechtliche Abklärung nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle müssen Regeln kennen"}, {"text": "Ja", "correct": false, "because": "Teamweites Wissen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Elemente werden abgeklärt?', 4, '[{"text": "Urheberrechte", "correct": true, "because": "Betreffen Software"}, {"text": "Teamgröße", "correct": false, "because": "Kein rechtlicher Aspekt"}, {"text": "Datenschutz", "correct": true, "because": "Schützt Daten"}, {"text": "Vertragsfristen", "correct": true, "because": "Regeln Zeitrahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die rechtliche Abklärung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis für Konformität"}, {"text": "Nein", "correct": false, "because": "Dokumentation schützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die rechtliche Abklärung?', 3, '[{"text": "Sicherung der Legalität", "correct": true, "because": "Verhindert Verstöße"}, {"text": "Kosten senken", "correct": false, "because": "Anderer Fokus"}, {"text": "Technische Lösung finden", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die rechtliche Abklärung ohne Experten erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Fachwissen oft nötig"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die rechtliche Abklärung?', 3, '[{"text": "Unklare Gesetzeslage", "correct": true, "because": "Verhindert Klarheit"}, {"text": "Klares Projektziel", "correct": false, "because": "Fördert Abklärung"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rechtliche Abklärung prüft Vorschriften. b) Sie ist nur für Kunden relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Unternehmen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel der rechtlichen Abklärung?', 3, '[{"text": "Vermeidung von Strafen", "correct": true, "because": "Schützt Projekt"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Team vergrößern", "correct": false, "because": "Anderer Fokus"}]');
